  header = (FAR const struct uvc_payload_header_s *)payload;
  header_len = header->bHeaderLength;

  if (header_len > len)
    {
      return;
    }

  data_len = len - header_len;
  data = payload + header_len;

  /* Detect MJPEG SOI (FF D8) at start of payload data.  If we already
   * have accumulated data and see a new JPEG start, the previous frame's
   * EOF was lost — deliver what we have and begin a new frame.
   */

  if (data_len >= 2 && data[0] == 0xff && data[1] == 0xd8 &&
      priv->frame_offset > 0)
