  static uint32_t s_frameno;    /* delivered frame counter */
  static uint8_t  s_lastfid;    /* previous payload's FID */
  static uint32_t s_fid_flip;   /* FID flips within current frame */

  if (len < 2)
    {
      return;
    }

  header = (FAR const struct uvc_payload_header_s *)payload;
  header_len = header->bHeaderLength;

  if (header_len > len)
    {
      return;
    }

  data_len = len - header_len;
  data = payload + header_len;
  fid = header->bmHeaderInfo & UVC_HEADER_FID;

  /* Track FID flips within a frame (should be 0 or 1 per frame normally) */

  if (s_pls > 0 && fid != s_lastfid)
    {
      s_fid_flip++;
    }

  s_lastfid = fid;

