            memcpy(priv->user_buf, priv->frame_buf, copy_len);
            priv->capture_cb(0, copy_len, 0, priv->capture_arg);
          }
        static uint32_t s_frameno, s_soi;
        syslog(LOG_ERR,
          "UVC-FRAME#%u SOI: sz=%u pls=%u\n",
          s_frameno++, (unsigned)priv->frame_offset, s_pls);
        s_soi++;
        priv->frame_offset = 0;
        s_pls = 0;
      }

    if (priv->frame_offset + data_len <= priv->frame_buflen)
      {
        memcpy(priv->frame_buf + priv->frame_offset, data, data_len);
        priv->frame_offset += data_len;
      }

    if (header->bmHeaderInfo & UVC_HEADER_EOF)
      {
        if (priv->frame_offset >= 1024 &&
            priv->capture_cb != NULL && priv->user_buf != NULL)
          {
            size_t copy_len = priv->frame_offset;
            if (copy_len > priv->user_buflen)
              copy_len = priv->user_buflen;
            memcpy(priv->user_buf, priv->frame_buf, copy_len);
            priv->capture_cb(0, copy_len, 0, priv->capture_arg);
          }
        static uint32_t s_frameno2, s_eof;
        syslog(LOG_ERR,
          "UVC-FRAME#%u EOF: sz=%u pls=%u\n",
          s_frameno2++, (unsigned)priv->frame_offset, s_pls);
        s_eof++;
        priv->frame_offset = 0;
        s_pls = 0;
      }

    if (priv->max_frame_size > 0 &&
        priv->frame_offset >= priv->max_frame_size)
      {
        static uint32_t s_frameno3, s_maxsz;
        syslog(LOG_ERR,
          "UVC-FRAME#%u MAXSZ: sz=%u pls=%u\n",
          s_frameno3++, (unsigned)priv->frame_offset, s_pls);
        s_maxsz++;
        priv->frame_offset = 0;
        s_pls = 0;
      }
  }

