25	/****************************************************************************
26	 * Pre-processor Definitions
27	 ****************************************************************************/
28	
29	#define VIDEO_DEV_PATH    "/dev/video"
30	#define FB_DEV_PATH       "/dev/lcd0"
31	#define TEST_WIDTH        320
32	#define TEST_HEIGHT       240
33	#define TEST_BUF_COUNT    6   /* Deeper queue: more vacant buffers for the UVC
34	                               * stream thread to rotate through, so it never
35	                               * wraps onto the buffer the app is copying out.
36	                               */
37	#define PREVIEW_FRAMES    300   /* ~10s at 30fps; 0 = run forever */
38	#define SAVE_FRAMES       10    /* Save first N frames as .yuv files to /data/ */
39	
40	/****************************************************************************
41	 * Private Types
42	 ****************************************************************************/
43	
44	struct v_buffer
45	{
46	  uint8_t *start;
47	  uint32_t length;
48	};
49	
50	/****************************************************************************
51	 * Private Data
52	 ****************************************************************************/
53	
54	static struct fb_videoinfo_s g_vinfo;
55	static int                   g_fbfd = -1;
56	static int                   g_recfd = -1;  /* /data/capture.yuv */
57	static uint16_t              g_rgbbuf[TEST_WIDTH * TEST_HEIGHT];
58	
59	/****************************************************************************
60	 * tjpgd callbacks for MJPEG decode
61	 ****************************************************************************/
62	
63	struct mjpeg_iodev_s
64	{
65	  const uint8_t *data;
66	  size_t         len;
67	  size_t         pos;
68	};
69	
70	static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
71	{
72	  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
73	  size_t avail = io->len - io->pos;
74	
75	  if (nbyte > avail)
76	    nbyte = avail;
77	
78	  if (buff)
79	    memcpy(buff, io->data + io->pos, nbyte);
80	
81	  io->pos += nbyte;
82	  return nbyte;
83	}
84	
85	static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
86	{
87	  uint8_t *src = (uint8_t *)bitmap;
88	  uint32_t x;
89	  uint32_t y;
90	  uint32_t w = rect->right - rect->left + 1;
91	  uint32_t cpw = jd->width < TEST_WIDTH ? jd->width : TEST_WIDTH;
92	
93	  for (y = rect->top; y <= rect->bottom && y < TEST_HEIGHT; y++)
94	    {
95	      for (x = rect->left; x <= rect->right && x < TEST_WIDTH; x++)
96	        {
97	          uint8_t r = *src++;
98	          uint8_t g = *src++;
99	          uint8_t b = *src++;
100	          g_rgbbuf[y * cpw + x] =
101	            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
102	        }
103	
104	      if (rect->right >= TEST_WIDTH)
105	        src += (rect->right - TEST_WIDTH + 1) * 3;
106	    }
107	
108	  return 1;
109	}
110	
111	/* Private snapshot of one captured frame (YUYV), so the shared V4L2 capture
112	 * buffer can be requeued immediately and not be overwritten mid-processing.
113	 */
114	
115	static uint8_t               g_framecopy[TEST_WIDTH * TEST_HEIGHT * 2];
116	
117	/****************************************************************************
118	 * Private Functions
119	 ****************************************************************************/
120	
121	/* Clamp an int to [0,255] */
122	
123	static inline uint8_t clamp8(int v)
124	{
125	  if (v < 0)
126	    {
127	      return 0;
128	    }
129	
130	  if (v > 255)
131	    {
132	      return 255;
133	    }
134	
135	  return (uint8_t)v;
136	}
137	
138	/****************************************************************************
139	 * Name: fb_open
140	 *
141	 * Description:
142	 *   Open the framebuffer device and query its geometry.
143	 *
144	 ****************************************************************************/
145	
146	static int fb_open(void)
147	{
148	  int ret;
149	
150	  g_fbfd = open(FB_DEV_PATH, O_RDWR);
151	  if (g_fbfd < 0)
152	    {
153	      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
154	      return -errno;
155	    }
156	
157	  /* /dev/lcd0 is an lcddev character device, use LCDDEVIO_GETVIDEOINFO */
158	
159	  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
160	  if (ret < 0)
161	    {
162	      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
163	      close(g_fbfd);
164	      g_fbfd = -1;
165	      return -errno;
166	    }
167	
168	  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
169	
170	  /* Also emit to syslog so it lands in the serial log for diagnosis. */
171	
172	  syslog(LOG_ERR, "UVCTEST LCD: xres=%u yres=%u fmt=%u\n",
173	         g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
174	
175	  return OK;
176	}
177	
178	/****************************************************************************
179	 * Name: fb_update
180	 *
181	 * Description:
182	 *   Notify the framebuffer driver that the content changed (for LCD
183	 *   drivers that need an explicit flush).
184	 *
185	 ****************************************************************************/
186	
187	static void fb_blit(uint32_t w, uint32_t h)
188	{
189	  struct lcddev_area_s area;
190	
191	  memset(&area, 0, sizeof(area));
192	  area.row_start = 0;
193	  area.row_end   = h - 1;
194	  area.col_start = 0;
195	  area.col_end   = w - 1;
196	  area.stride    = w * 2;          /* RGB565: 2 bytes/pixel */
197	  area.data      = (FAR uint8_t *)g_rgbbuf;
198	
199	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
200	}
201	
202	/****************************************************************************
203	 * Name: yuyv_to_fb
204	 *
205	 * Description:
206	 *   Convert a YUYV 4:2:2 frame to the framebuffer's RGB565 format and
207	 *   blit it centered on the screen.
208	 *
209	 ****************************************************************************/
210	
211	static void yuyv_to_fb(FAR const uint8_t *yuyv, uint32_t len)
212	{
213	  uint32_t panel_w = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
214	  uint32_t panel_h = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
215	  uint32_t cpw = (panel_w < TEST_WIDTH)  ? panel_w : TEST_WIDTH;
216	  uint32_t cph = (panel_h < TEST_HEIGHT) ? panel_h : TEST_HEIGHT;
217	  uint32_t x;
218	  uint32_t y;
219	
220	  for (y = 0; y < cph; y++)
221	    {
222	      FAR const uint8_t *src = yuyv + y * TEST_WIDTH * 2;
223	      FAR uint16_t *dst = &g_rgbbuf[y * cpw];
224	
225	      if ((size_t)(y * TEST_WIDTH * 2) + cpw * 2 > len)
226	        {
227	          break;
228	        }
229	
230	      for (x = 0; x + 1 < cpw; x += 2)
231	        {
232	          int y0 = src[0];
233	          int u  = src[1] - 128;
234	          int y1 = src[2];
235	          int v  = src[3] - 128;
236	
237	          dst[x] = ((clamp8(y0 + ((179 * v) >> 7)) & 0xf8) << 8) |
238	                   ((clamp8(y0 - ((44 * u) >> 7) - ((91 * v) >> 7)) & 0xfc) << 3) |
239	                   (clamp8(y0 + ((227 * u) >> 7)) >> 3);
240	
241	          dst[x + 1] = ((clamp8(y1 + ((179 * v) >> 7)) & 0xf8) << 8) |
242	                       ((clamp8(y1 - ((44 * u) >> 7) - ((91 * v) >> 7)) & 0xfc) << 3) |
243	                       (clamp8(y1 + ((227 * u) >> 7)) >> 3);
244	
245	          src += 4;
246	        }
247	    }
248	
249	  fb_blit(cpw, cph);
250	}
251	
252	/****************************************************************************
253	 * Public Functions
254	 ****************************************************************************/
255	
256	int uvc_test_main(int argc, char *argv[])
257	{
258	  struct v4l2_format fmt;
259	  struct v4l2_requestbuffers req;
260	  struct v4l2_buffer buf;
261	  struct v_buffer *buffers;
262	  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
263	  int fd;
264	  int ret;
265	  int i;
266	  int frames = 0;
267	
268	  printf("=== USB Camera (UVC) Live Preview ===\n");
269	
270	  /* Open the framebuffer for display */
271	
272	  ret = fb_open();
273	  if (ret < 0)
274	    {
275	      printf("ERROR: framebuffer init failed\n");
276	      return ERROR;
277	    }
278	
279	  /* DIAG: draw a static test pattern (colored horizontal bars) once, before
280	   * any camera data, to isolate the blit/LCD path from the camera data.  If
281	   * these bars appear clean and aligned, the LCD geometry+blit is correct and
282	   * any stripes are in the camera-frame layout; if the bars themselves are
283	   * striped/torn, the problem is in the blit or LCD driver path.
284	   */
285	
286	  {
287	    uint32_t pw = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
288	    uint32_t ph = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
289	    uint32_t xx;
290	    uint32_t yy;
291	
292	    if (pw > TEST_WIDTH)  pw = TEST_WIDTH;
293	    if (ph > TEST_HEIGHT) ph = TEST_HEIGHT;
294	
295	    for (yy = 0; yy < ph; yy++)
296	      {
297	        uint16_t color;
298	        if      (yy < ph / 4)     color = 0xf800;  /* red    */
299	        else if (yy < ph / 2)     color = 0x07e0;  /* green  */
300	        else if (yy < ph * 3 / 4) color = 0x001f;  /* blue   */
301	        else                      color = 0xffff;  /* white  */
302	
303	        for (xx = 0; xx < pw; xx++)
304	          {
305	            g_rgbbuf[yy * pw + xx] = color;
306	          }
307	      }
308	
309	    fb_blit(pw, ph);
310	    syslog(LOG_ERR, "UVCTEST testpattern blitted %ux%u\n", pw, ph);
311	    sleep(2);
312	  }
313	
314	  /* Initialize video driver (creates /dev/video device) */
315	
316	  ret = capture_initialize(VIDEO_DEV_PATH);
317	  if (ret != 0)
318	    {
319	      printf("ERROR: Failed to initialize video: %d (errno=%d)\n", ret, errno);
320	      return ERROR;
321	    }
322	
323	  fd = open(VIDEO_DEV_PATH, O_RDWR);
324	  if (fd < 0)
325	    {
326	      printf("ERROR: Failed to open %s: %d\n", VIDEO_DEV_PATH, errno);
327	      return ERROR;
328	    }
329	
330	  /* Set YUYV format */
331	
332	  memset(&fmt, 0, sizeof(fmt));
333	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
334	  fmt.fmt.pix.width = TEST_WIDTH;
335	  fmt.fmt.pix.height = TEST_HEIGHT;
336	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
337	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
338	
339	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
340	  if (ret < 0)
341	    {
342	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
343	      goto err_close;
344	    }
345	
346	  if (fmt.fmt.pix.sizeimage == 0)
347	    {
348	      fmt.fmt.pix.sizeimage = TEST_WIDTH * TEST_HEIGHT * 2;
349	    }
350	
351	  /* Request buffers */
352	
353	  memset(&req, 0, sizeof(req));
354	  req.count = TEST_BUF_COUNT;
355	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
356	  req.memory = V4L2_MEMORY_USERPTR;
357	
358	  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
359	  if (ret < 0)
360	    {
361	      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
362	      goto err_close;
363	    }
364	
365	  buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
366	  if (buffers == NULL)
367	    {
368	      printf("ERROR: Failed to allocate buffer array\n");
369	      goto err_close;
370	    }
371	
372	  for (i = 0; i < req.count; i++)
373	    {
374	      buffers[i].length = fmt.fmt.pix.sizeimage;
375	      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
376	      if (buffers[i].start == NULL)
377	        {
378	          printf("ERROR: Failed to allocate buffer %d\n", i);
379	          goto err_free_buffers;
380	        }
381	
382	      memset(&buf, 0, sizeof(buf));
383	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
384	      buf.memory = V4L2_MEMORY_USERPTR;
385	      buf.index = i;
386	      buf.m.userptr = (uintptr_t)buffers[i].start;
387	      buf.length = buffers[i].length;
388	
389	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
390	      if (ret < 0)
391	        {
392	          printf("ERROR: VIDIOC_QBUF failed for buffer %d: %d\n", i, errno);
393	          goto err_free_buffers;
394	        }
395	    }
396	
397	  /* Start streaming */
398	
399	  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
400	  if (ret < 0)
401	    {
402	      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
403	      goto err_free_buffers;
404	    }
405	
406	  printf("Live preview started (press Ctrl-C to stop)\n");
407	
408	  /* Preview loop */
409	
410	  while (PREVIEW_FRAMES == 0 || frames < PREVIEW_FRAMES)
411	    {
412	      memset(&buf, 0, sizeof(buf));
413	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
414	      buf.memory = V4L2_MEMORY_USERPTR;
415	
416	      ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
417	      if (ret < 0)
418	        {
419	          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
420	          break;
421	        }
422	
423	      /* Snapshot the frame into a private buffer, then IMMEDIATELY requeue
424	       * the V4L2 buffer.  The UVC stream thread writes the next frame into
425	       * one of the shared capture buffers concurrently; if the app kept a
426	       * buffer for the whole convert+SPI-blit time (slow, per-row SPI), the
427	       * driver could wrap around and overwrite the buffer mid-read, showing
428	       * up as a moving horizontal "tear" band.  Copying out fast (one memcpy)
429	       * and requeuing at once shrinks that window to almost nothing.
430	       */
431	
432	      {
433	        uint32_t n = buf.bytesused;
434	        if (n > sizeof(g_framecopy))
435	          {
436	            n = sizeof(g_framecopy);
437	          }
438	
439	        memcpy(g_framecopy, (const void *)buf.m.userptr, n);
440	
441	        /* Requeue immediately, before the slow convert + blit. */
442	
443	        ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
444	        if (ret < 0)
445	          {
446	            printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
447	            break;
448	          }
449	
450	      /* MJPEG: decode JPEG via tjpgd and blit to LCD. */
451	
452	      if (n > 1024)
453	        {
454	          static uint8_t jdwork[4096];  /* tjpgd work buffer */
455	          JDEC jdec;
456	          JRESULT res;
457	          struct mjpeg_iodev_s iodev;
458	
459	          iodev.data = g_framecopy;
460	          iodev.len  = n;
461	          iodev.pos  = 0;
462	
463	          res = jd_prepare(&jdec, mjpeg_input, jdwork,
464	                           sizeof(jdwork), &iodev);
465	          if (res == JDR_OK)
466	            {
467	              jd_decomp(&jdec, mjpeg_output, 0);
468	              fb_blit(jdec.width < TEST_WIDTH ? jdec.width : TEST_WIDTH,
469	                      jdec.height < TEST_HEIGHT ? jdec.height : TEST_HEIGHT);
470	            }
471	        }
472	
473	      frames++;
474	
475	      }
476	    }
477	
478	  /* Stop streaming */
479	
480	  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
481	  printf("Preview stopped after %d frames\n", frames);
482	
483	  /* Uninitialize video driver so /dev/video can be re-opened. */
484	
485	  capture_uninitialize(VIDEO_DEV_PATH);
486	
487	  ret = OK;
488	
489	err_free_buffers:
490	  for (i = 0; i < req.count; i++)
491	    {
492	      if (buffers[i].start != NULL)
493	        {
494	          free(buffers[i].start);
495	        }
496	    }
497	
498	  free(buffers);
499	
500	err_close:
501	  close(fd);
502	  if (g_fbfd >= 0)
503	    {
504	      close(g_fbfd);
505	    }
506	
507	  return ret;
508	}
