/****************************************************************************
 * apps/examples/uvc_test/uvc_test.c
 *
 * USB Camera (UVC) single-frame capture — diagnostic mode
 * Captures one MJPEG frame and saves it to /data/photo.jpg
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/ioctl.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>
#include <nuttx/video/fb.h>
#include <nuttx/lcd/lcd_dev.h>
#include "tjpgd.h"

#define VIDEO_DEV_PATH    "/dev/video"
#define FB_DEV_PATH       "/dev/lcd0"
#define TEST_WIDTH        320
#define TEST_HEIGHT       240
#define TEST_BUF_COUNT    6

static struct fb_videoinfo_s g_vinfo;
static int                   g_fbfd = -1;
static uint16_t              g_rgbbuf[TEST_WIDTH * TEST_HEIGHT];

/* tjpgd callbacks for MJPEG decode */

struct mjpeg_iodev_s
{
  const uint8_t *data;
  size_t         len;
  size_t         pos;
};

static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
{
  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;

  if (nbyte > avail)
    nbyte = avail;

  if (buff)
    memcpy(buff, io->data + io->pos, nbyte);

  io->pos += nbyte;
  return nbyte;
}

static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
{
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t x;
  uint32_t y;
  uint32_t cpw = jd->width < TEST_WIDTH ? jd->width : TEST_WIDTH;

  for (y = rect->top; y <= rect->bottom && y < TEST_HEIGHT; y++)
    {
      for (x = rect->left; x <= rect->right && x < TEST_WIDTH; x++)
        {
          uint8_t r = *src++;
          uint8_t g = *src++;
          uint8_t b = *src++;
          g_rgbbuf[y * cpw + x] =
            ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
        }

      if (rect->right >= TEST_WIDTH)
        src += (rect->right - TEST_WIDTH + 1) * 3;
    }

  return 1;
}

static void fb_blit(uint32_t w, uint32_t h)
{
  struct lcddev_area_s area;

  memset(&area, 0, sizeof(area));
  area.row_start = 0;
  area.row_end   = h - 1;
  area.col_start = 0;
  area.col_end   = w - 1;
  area.stride    = w * 2;
  area.data      = (FAR uint8_t *)g_rgbbuf;

  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
}

static int fb_open(void)
{
  int ret;

  g_fbfd = open(FB_DEV_PATH, O_RDWR);
  if (g_fbfd < 0)
    {
      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
      return -errno;
    }

  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
  if (ret < 0)
    {
      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
      close(g_fbfd);
      g_fbfd = -1;
      return -errno;
    }

  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
  syslog(LOG_ERR, "UVCTEST LCD: xres=%u yres=%u fmt=%u\n",
         g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
  return OK;
}

int uvc_test_main(int argc, char *argv[])
{
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  struct v_buffer *buffers;
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  int fd;
  int ret;
  int i;
  int savefd;

  printf("=== UVC Single-Frame Capture (Diagnostic) ===\n");

  /* Open framebuffer */

  ret = fb_open();
  if (ret < 0)
    {
      printf("ERROR: framebuffer init failed\n");
      return ERROR;
    }

  /* Draw test pattern */

  {
    uint32_t pw = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
    uint32_t ph = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
    uint32_t xx, yy;

    if (pw > TEST_WIDTH)  pw = TEST_WIDTH;
    if (ph > TEST_HEIGHT) ph = TEST_HEIGHT;

    for (yy = 0; yy < ph; yy++)
      {
        uint16_t color;
        if      (yy < ph / 4)     color = 0xf800;
        else if (yy < ph / 2)     color = 0x07e0;
        else if (yy < ph * 3 / 4) color = 0x001f;
        else                      color = 0xffff;

        for (xx = 0; xx < pw; xx++)
          g_rgbbuf[yy * pw + xx] = color;
      }

    fb_blit(pw, ph);
    syslog(LOG_ERR, "UVCTEST testpattern blitted %ux%u\n", pw, ph);
    sleep(2);
  }

  /* Initialize video driver */

  ret = capture_initialize(VIDEO_DEV_PATH);
  if (ret != 0)
    {
      printf("ERROR: Failed to initialize video: %d\n", ret);
      return ERROR;
    }

  fd = open(VIDEO_DEV_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", VIDEO_DEV_PATH, errno);
      return ERROR;
    }

  /* Set MJPEG format */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = TEST_WIDTH;
  fmt.fmt.pix.height = TEST_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field = V4L2_FIELD_NONE;

  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
      goto err_close;
    }

  if (fmt.fmt.pix.sizeimage == 0)
    fmt.fmt.pix.sizeimage = TEST_WIDTH * TEST_HEIGHT * 2;

  /* Request buffers */

  memset(&req, 0, sizeof(req));
  req.count = TEST_BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
      goto err_close;
    }

  buffers = malloc(req.count * sizeof(struct v_buffer));
  if (buffers == NULL)
    {
      printf("ERROR: malloc buffers\n");
      goto err_close;
    }

  for (i = 0; i < req.count; i++)
    {
      buffers[i].length = fmt.fmt.pix.sizeimage;
      buffers[i].start = memalign(64, buffers[i].length);
      if (buffers[i].start == NULL)
        {
          printf("ERROR: alloc buffer %d\n", i);
          goto err_free_buffers;
        }

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_USERPTR;
      buf.index = i;
      buf.m.userptr = (uintptr_t)buffers[i].start;
      buf.length = buffers[i].length;

      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF buf %d: %d\n", i, errno);
          goto err_free_buffers;
        }
    }

  /* Start streaming */

  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_STREAMON: %d\n", errno);
      goto err_free_buffers;
    }

  printf("Waiting for first frame...\n");

  /* Capture exactly ONE frame */

  memset(&buf, 0, sizeof(buf));
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  buf.memory = V4L2_MEMORY_USERPTR;

  ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_DQBUF: %d\n", errno);
      goto err_streamoff;
    }

  printf("Got frame: bytesused=%u\n", buf.bytesused);
  syslog(LOG_ERR, "UVCTEST-CAPTURE: bytesused=%u\n", buf.bytesused);

  /* Dump first 32 bytes for header inspection */

  {
    const uint8_t *p = (const uint8_t *)buf.m.userptr;
    uint32_t n = buf.bytesused;
    syslog(LOG_ERR, "UVCTEST-JPEG-HEAD: %02x %02x %02x %02x "
           "%02x %02x %02x %02x-%02x %02x %02x %02x %02x %02x %02x %02x\n",
           n >= 1  ? p[0]  : 0, n >= 2  ? p[1]  : 0,
           n >= 3  ? p[2]  : 0, n >= 4  ? p[3]  : 0,
           n >= 5  ? p[4]  : 0, n >= 6  ? p[5]  : 0,
           n >= 7  ? p[6]  : 0, n >= 8  ? p[7]  : 0,
           n >= 9  ? p[8]  : 0, n >= 10 ? p[9]  : 0,
           n >= 11 ? p[10] : 0, n >= 12 ? p[11] : 0,
           n >= 13 ? p[12] : 0, n >= 14 ? p[13] : 0,
           n >= 15 ? p[14] : 0, n >= 16 ? p[15] : 0);

    /* Check last 2 bytes for JPEG EOI (FF D9) */
    if (n >= 2)
      {
        syslog(LOG_ERR, "UVCTEST-JPEG-TAIL: %02x %02x\n",
               p[n - 2], p[n - 1]);
      }
  }

  /* Requeue buffer */

  ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
  if (ret < 0)
    printf("ERROR: VIDIOC_QBUF: %d\n", errno);

  /* Save JPEG to file */

  savefd = open("/data/photo.jpg", O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (savefd >= 0)
    {
      ssize_t written = write(savefd, (const void *)buf.m.userptr,
                              buf.bytesused);
      close(savefd);
      printf("Saved /data/photo.jpg: %d bytes\n", (int)written);
      syslog(LOG_ERR, "UVCTEST-SAVE: wrote %d bytes to /data/photo.jpg\n",
             (int)written);
    }
  else
    {
      printf("ERROR: cannot create /data/photo.jpg: %d\n", errno);
    }

  /* Decode and display */

  if (buf.bytesused > 1024)
    {
      static uint8_t jdwork[4096];
      JDEC jdec;
      JRESULT res;
      struct mjpeg_iodev_s iodev;

      iodev.data = (const uint8_t *)buf.m.userptr;
      iodev.len  = buf.bytesused;
      iodev.pos  = 0;

      res = jd_prepare(&jdec, mjpeg_input, jdwork, sizeof(jdwork), &iodev);
      if (res == JDR_OK)
        {
          jd_decomp(&jdec, mjpeg_output, 0);
          fb_blit(jdec.width < TEST_WIDTH ? jdec.width : TEST_WIDTH,
                  jdec.height < TEST_HEIGHT ? jdec.height : TEST_HEIGHT);
          printf("Decoded %ux%u JPEG, displayed\n",
                 jdec.width, jdec.height);
          syslog(LOG_ERR, "UVCTEST-DECODE: %ux%u OK\n",
                 jdec.width, jdec.height);
        }
      else
        {
          printf("JPEG decode failed: %d\n", res);
          syslog(LOG_ERR, "UVCTEST-DECODE-FAIL: res=%d\n", res);
        }
    }

  printf("Done. Check /data/photo.jpg on device.\n");

err_streamoff:
  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
  capture_uninitialize(VIDEO_DEV_PATH);

err_free_buffers:
  for (i = 0; i < req.count; i++)
    {
      if (buffers[i].start != NULL)
        free(buffers[i].start);
    }
  free(buffers);

err_close:
  close(fd);
  if (g_fbfd >= 0)
    close(g_fbfd);

  return ret;
}

